window.__BUNDLE__={"generatedAt":"2026-08-27T14:35:25.790664+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-08-20","archiveCutoff":"2021-08-28","addedToday":104,"addedThisRun":104,"fetchStats":{"hf":212,"arxiv":1325,"total":1537},"freshness":{"latestPaperDate":"2026-08-27","latestPublishedDate":"2026-08-27","latestBatchCount":270,"newInLast24h":306,"newInLast48h":613},"historyTotal":9346,"topicCounts":{"Multi-Agent":1711,"Evaluation":4767,"Planning":835,"Memory":208,"Code Agent":485,"Interpretability":322,"Agentic RAG":949,"Agentic Search":1153,"RL for LLM":715,"Reasoning":2937,"Hallucination":570,"Post-Training":1337,"Alignment":1241,"World Model":103,"Tool Use":1017,"Agent Safety":1982,"Computer Use":205,"Reflection":407,"VLM Training":452,"LLM Training":1006,"Fine-tuning":1362,"Multimodal Agent":58,"Agent Framework":623,"Error Attribution":84,"Data Engine":202},"count":36,"recentTotal":1789,"archiveCount":0,"archiveTotal":7557,"sources":{"hf":21,"arxiv":1767,"semanticScholar":1},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"source":"hf","upvotes":134,"url":"https://arxiv.org/abs/2608.26005","title":"VoiceMem: Streaming Dual-Brain Memory for Real-Time Interaction","pdf":"https://arxiv.org/pdf/2608.26005.pdf","authors":["Zhifei Xie","Jiaqi Lang","Ze An","Yifan Zhao","Dongchao Yang","Kai Li","Ziyang Ma","Mingbao Lin","Chunyan Miao","Shuicheng Yan"],"submittedDate":"2026-08-26","tags":["Evaluation"],"arxiv":"https://arxiv.org/abs/2608.26005","date":"2026-08-27","hfUrl":"https://huggingface.co/papers/2608.26005","topics":["Evaluation"],"id":"arxiv:2608.26005","announceDate":"2026-08-27","abstract":"Conversational systems, such as duplex speech language models (SLMs), still lack a streaming, accurate, and empathetic memory system as their soul. We introduce VoiceMem, a simple memory architecture with a parallel informational left brain, an emotional right brain, and streaming memory I/O mechanisms. We further build a complete pipeline for memory-aware SLM training, long-horizon evaluation, and decoupled deployment with interchangeable memory backends. Experiments and real-world deployment show three advantages: i) Accuracy: under top-5 retrieval, the left brain outperforms classical systems such as Mem0 at top-200 by nearly 30 points; ii) Emotional & Personal: the right brain, with short- and long-horizon affective attribution and dual-node persona modeling, achieves state-of-the-art performance across three persona benchmarks and improves the aggregate score by 4.29 points over the"},{"source":"hf","upvotes":38,"url":"https://arxiv.org/abs/2608.26105","title":"VBVR-Pro: A Scalable and Verifiable Suite for Native Visual Reasoning","pdf":"https://arxiv.org/pdf/2608.26105.pdf","authors":["Junxiang Xu","Ruisi Wang","Fanyi Pu","Maijunxian Wang","Ran Ji","Tongxi Zhou","Chenyang Gu","Jing Zuo","Hongcan Xiao","Yimeng Geng","Wanqi Yin","Wei Chen","Oscar Qian","Zhengan Yan","Ziqi Huang","Haiwen Diao","Liang Pan","Bo Li","Xiangyu Fan","Dezhi Luo","Fengyuan Yu","Zehong Zhao","Qingying Gao","Tinghui Zhu","Yilan Zhang","Jingqi Tong","Pinyuan Feng","Zhengze Jiang","Letian Wang","Ziyu Guo","Renrui Zhang","Jieneng Chen","Sonia Joseph","Constantin Venhoff","Saman Motamed","Mengyue Yang","Chandra Sripada","Alan Yuille","Philip Torr","Lvmin Zhang","Vikash Kumar","Daniel Khashabi","Nikolaus Kriegeskorte","Raphaël Millière","Vincent C. Müller","Anyi Rao","Quan Wang","Ziwei Liu","Dahua Lin","Lei Yang","Hokin Deng","Zhongang Cai"],"submittedDate":"2026-08-26","tags":["VLM Training","Reasoning","Evaluation","Alignment","RL for LLM"],"arxiv":"https://arxiv.org/abs/2608.26105","date":"2026-08-27","hfUrl":"https://huggingface.co/papers/2608.26105","topics":["VLM Training","Reasoning","Evaluation","Alignment","RL for LLM"],"id":"arxiv:2608.26105","announceDate":"2026-08-27","abstract":"Native visual reasoning treats visual generation as the medium of reasoning itself: visual states (i.e. images and videos) are not merely inputs to be understood or outputs to be rendered, but first-class substrates for problem solving beyond language. Yet progress remains bottlenecked by the lack of scalable training tasks, reliable feedback, and controlled comparisons across generative substrates. In this work, we introduce VBVR-Pro, a closed-loop testbed that makes native visual reasoning through generation trainable, verifiable, optimizable, and experimentally controllable. 1) Task scaling. VBVR-Pro turns visual reasoning into a controlled task space of 300 procedurally generated tasks. Models trained on VBVR-Pro show strong transfer beyond the proposed suite across seven external visual reasoning benchmarks such as RISE-Video, MME-CoF-Pro, and BabyVision. 2) Verifiable rewards. VBVR"},{"source":"hf","upvotes":15,"url":"https://arxiv.org/abs/2608.26067","title":"StreamPI: Streaming Multimodal Temporal Modeling for Vision-Language-Action Models","pdf":"https://arxiv.org/pdf/2608.26067.pdf","authors":["Zhe Liu","Jinghua Hou","Yuxiang Lu","Zhenya Yang","Xianzhe Fan","Junwei Luo","Junyi Li","Ruihua Han","Zhi Hou","Hengshuang Zhao"],"submittedDate":"2026-08-26","tags":["VLM Training","Reasoning","Evaluation"],"arxiv":"https://arxiv.org/abs/2608.26067","date":"2026-08-27","hfUrl":"https://huggingface.co/papers/2608.26067","topics":["VLM Training","Reasoning","Evaluation"],"id":"arxiv:2608.26067","announceDate":"2026-08-27","abstract":"Vision-Language-Action (VLA) models have demonstrated effectiveness in robot manipulation, yet state-of-the-art models such as pi0.5 operate under a single-frame paradigm, limiting their ability to retain past observations and develop precise spatial perception. In this paper, we propose StreamPI, a streaming multimodal temporal modeling framework that equips single-frame VLA with temporal reasoning capability without introducing any additional parameters. One core design is instruction-anchored temporal modeling. It treats each (visual observation, language instruction) pair as an atomic temporal unit: bidirectional attention within each pair enables cross-modal fusion, while causal attention across pairs preserves autoregressive streaming inference. This ensures the language instruction serves as a persistent semantic anchor throughout task execution. To bridge the gap between synchron"},{"source":"hf","upvotes":5,"url":"https://arxiv.org/abs/2608.25864","title":"MA-VLA: Multi-Arm Vision-Language-Action Model for Collaboration and Compositional Generalization","pdf":"https://arxiv.org/pdf/2608.25864.pdf","authors":["Zaibin Zhang","Junlan Xiao","Zhongbo Zhang","Yifan Wang","Li Kang","Yiran Qin","Changxing Xia","Heng Zhou","Talas Fu","Enshen Zhou","Ruimao Zhang","Zhenfei Yin","Huchuan Lu","Lijun Wang"],"tags":["VLM Training","Evaluation"],"arxiv":"https://arxiv.org/abs/2608.25864","date":"2026-08-27","hfUrl":"https://huggingface.co/papers/2608.25864","topics":["VLM Training","Evaluation"],"id":"arxiv:2608.25864","abstract":"Multi-arm collaboration is becoming a core capability in embodied manipulation. Recent vision-language-action (VLA) models integrate perception, language, and control, but most represent language as a single global instruction and do not provide an explicit mechanism for assigning and composing arm-specific behaviors. This design limits transfer to collaboration patterns that differ from those observed during training. We present MA-VLA, a unified framework for multi-arm collaboration via atomic action assignment. MA-VLA decomposes cooperative behavior into mid-level atomic prompts and allocates them to individual arms, enabling explicit subgoal specification and compositional reuse across tasks. To reduce reliance on fixed execution roles, we introduce Arm Shuffle, a training-time permutation of the observation, state, and assigned atomic prompts for each arm. This permutation enforces "},{"source":"hf","upvotes":1,"url":"https://arxiv.org/abs/2608.26070","title":"Prefix Sliding for efficient test-time scaling","pdf":"https://arxiv.org/pdf/2608.26070.pdf","authors":["Niklas Muennighoff","Zhengyang Wang","Zeyi Chen","Weijia Shi","Binyuan Hui","John Yang","Dapeng Jiang","Mika Senghaas","Fares Obeid","Johannes Hagemann","Sami Jaghouar","Ludwig Schmidt","Percy Liang","Jason Wei","Andrew Y. Ng","Luke Zettlemoyer","Yejin Choi","Mike Lewis"],"submittedDate":"2026-08-26","tags":["Reasoning","RL for LLM"],"arxiv":"https://arxiv.org/abs/2608.26070","date":"2026-08-27","hfUrl":"https://huggingface.co/papers/2608.26070","topics":["Reasoning","RL for LLM"],"id":"arxiv:2608.26070","announceDate":"2026-08-27","abstract":"Test-time scaling uses extra test-time compute to improve performance, such as letting language models reason longer when solving a problem. As models keep the entire reasoning trace in memory via full attention, hard tasks that need long thinking can be prohibitively expensive. However, we find most intermediate reasoning tokens lose importance as the model continues reasoning. This calls into question whether retaining them is worth the cost. Based on this insight, we propose Prefix Sliding, which discards tokens during reasoning that are not part of the prefix or the window of the last few thousand tokens. The prefix has key instructions and tools available to the model, while the most recent tokens are the current reasoning the model is working on. This caps the total memory requirement regardless of how long the model reasons, allowing for efficient long-horizon test-time scaling. W"},{"source":"hf","upvotes":1,"url":"https://arxiv.org/abs/2608.24909","title":"Super Star: Towards Streaming Real-time Interactive Agents for Digital Humans","pdf":"https://arxiv.org/pdf/2608.24909.pdf","authors":["Wentao Jiang","Youchen Xie","Haidi Fan","Yajing Chen","Xin Wang","Ye Shi","Jingya Wang"],"submittedDate":"2026-07-22","tags":["Data Engine"],"arxiv":"https://arxiv.org/abs/2608.24909","date":"2026-08-27","hfUrl":"https://huggingface.co/papers/2608.24909","topics":["Data Engine"],"id":"arxiv:2608.24909","announceDate":"2026-08-27","abstract":"Existing co-speech gesture generation methods are predominantly studied in offline settings, where gestures are synthesized from complete speech segments. However, interactive digital humans in real-world scenarios are required to generate speech-synchronous gestures online, using only currently available response audio under strict latency constraints. As a result, prior methods are unsuitable for real-time interaction, as they either rely on future speech information or incur substantial inference delay. In this paper, we formulate online co-speech gesture generation for interactive digital humans and propose a real-time interactive framework that couples a streaming speech response module with an online gesture generation module. Specifically, the gesture generator is designed as a causal multimodal autoregressive model that predicts body motion from streaming response speech and moti"},{"source":"arxiv","upvotes":118,"url":"https://arxiv.org/abs/2608.24979","title":"FrontierChallenge: Evaluating Scientific Workflow Completion","pdf":"https://arxiv.org/pdf/2608.24979.pdf","authors":["Liangcai Su","Zhaopeng Feng","Zhuo Chen","Zhen Zhang","Xiang Lin","Ruilin Li","Handuo Zhang","Ning Wang","Kailong Wen","Yueqi Guo","Feng Xing","Yiling Guo","Chenxiong Qian","Simon Shaolei Du","Lidong Bing","Xinyu Wang"],"submittedDate":"2026-08-25","tags":["Evaluation"],"arxiv":"https://arxiv.org/abs/2608.24979","date":"2026-08-27","hfUrl":"https://huggingface.co/papers/2608.24979","topics":["Evaluation"],"id":"arxiv:2608.24979","announceDate":"2026-08-27","abstract":"Scientific agents increasingly analyze data, execute code, and produce research artifacts, yet most benchmarks emphasize final answers, isolated programs, or a single domain. We introduce FrontierChallenge, a cross-domain benchmark comprising 300 end-to-end scientific workflows. In this paper, we release and evaluate 97 of these tasks, spanning quantum chemistry, molecular dynamics, materials characterization, analytical chemistry, life science, and electrochemistry/environment. Each task provides fixed inputs and specifies a bundle of required scientific deliverables. We evaluate twelve frontier models with three agent scaffolds. Pass Rate measures the fraction of tasks satisfying the full-completion criterion, while Avg. Score captures partial progress. Each of the best-performing configurations completed only 20 of the 97 released tasks, yielding a Pass Rate of 20.6%. Partial progress"},{"source":"arxiv","upvotes":46,"url":"https://arxiv.org/abs/2608.25593","title":"JIT-Agent: Scaling Harness Intelligence via Just-in-Time Harness Evolution","pdf":"https://arxiv.org/pdf/2608.25593.pdf","authors":["Guibin Zhang","Leo Lu","Fangzhou Xie","Kang Zhu","Junhao Wang","Zhifei Xie","Zhaochen Yu","Zihang Liu","Zhongxiang Sun","Qiankun Li","Yue Liao","Heng Chang","Xiaobin Hu","Qibing Ren","Wangchunshu Zhou","Shuicheng Yan"],"submittedDate":"2026-08-26","tags":["Planning","Evaluation"],"arxiv":"https://arxiv.org/abs/2608.25593","date":"2026-08-27","hfUrl":"https://huggingface.co/papers/2608.25593","topics":["Planning","Evaluation"],"id":"arxiv:2608.25593","announceDate":"2026-08-27","abstract":"Agent capability is not determined by the model alone. The agent harness, encompassing memory management, planning strategy, action protocol, and tool/skill orchestration, can dominate the contribution of the underlying foundation model. Yet harness design remains manual, task-specific, and fundamentally unscalable. We present JIT-Agent, a harness intelligence model trained to synthesize task-adaptive agent harnesses on the fly for arbitrary off-the-shelf agentic LLMs. We formalize the agent harness as a composable, machine-generatable artifact governed by a fixed four-module protocol, and train JIT-Agent to customize harnesses for a given task at hand, repair harnesses for stable and reliable execution, and self-evolve by distilling performance signals from an expanding archive of prior harness configurations. Equipped with JIT-Agent as a harness helper, DeepSeek-V4-Flash surpasses GPT-"},{"source":"arxiv","upvotes":14,"url":"https://arxiv.org/abs/2608.25529","title":"Video-IFBench: Evaluating Instruction Following of Multimodal LLMs in Video Understanding Scenarios","pdf":"https://arxiv.org/pdf/2608.25529.pdf","authors":["Hongbo Liu","Peixian Chen","Sihan Liu","Peiyuan Zhang","Kai Zou","Dian Zheng","Xiaoxing Hu","Yuhao Dong","Mengdan Zhang","Yunhang Shen","Haoyu Cao","Wei Liu","Weibo Gu","Xing Sun","Shengjie Zhao"],"submittedDate":"2026-08-26","tags":["Evaluation"],"arxiv":"https://arxiv.org/abs/2608.25529","date":"2026-08-27","hfUrl":"https://huggingface.co/papers/2608.25529","topics":["Evaluation"],"id":"arxiv:2608.25529","announceDate":"2026-08-27","abstract":"Multimodal Large Language Models (MLLMs) have shown strong performance in video understanding. However, their ability to follow instructions in this domain remains under-explored. Real-world video understanding requires models not only to interpret video content correctly, but also to satisfy diverse user-specified constraints. Existing benchmarks focus primarily on task accuracy rather than instruction adherence, leaving this capability insufficiently evaluated. To address this gap, we introduce Video-IFBench, a comprehensive benchmark for evaluating instruction following in video understanding, where models must satisfy diverse user-specified constraints, including those grounded in visual and audio content. We develop an instruction taxonomy with four templates, including single-task, multi-task, selection, and nested instructions, covering 32 task types and 39 manually designed const"},{"source":"arxiv","upvotes":12,"url":"https://arxiv.org/abs/2608.25580","title":"V-Rubrics: Visual Faithfulness via Rubric-Based Reinforcement Learning","pdf":"https://arxiv.org/pdf/2608.25580.pdf","authors":["Shulin Tian","Minglun Li","Yuhao Dong","Hao Ding","Jiarui Yao","Haiwen Diao","Jingkang Yang","Hongyuan Zhu","Ziwei Liu"],"submittedDate":"2026-08-26","tags":["Post-Training","LLM Training","VLM Training","Reasoning","Hallucination"],"arxiv":"https://arxiv.org/abs/2608.25580","date":"2026-08-27","hfUrl":"https://huggingface.co/papers/2608.25580","topics":["Post-Training","LLM Training","VLM Training","Reasoning","Hallucination","Evaluation","Fine-tuning","RL for LLM"],"id":"arxiv:2608.25580","announceDate":"2026-08-27","abstract":"Vision-language models can produce fluent answers that are insufficiently grounded in the visual evidence: a single unsupported object, chart value, or intermediate inference can undermine an otherwise plausible response. We argue that this is a credit-assignment failure in multimodal post-training. Scalar outcome rewards indicate whether an answer is acceptable, but do not identify which visual facts are grounded, which reasoning steps are valid, or which instruction constraints are missed. We introduce Visual Rubrics-Based Reinforcement Learning, which decomposes reference responses into atomic propositions and scores generated answers along Visual Faithfulness (VF), Reasoning Consistency (RC), and Instruction Following (IF). The resulting rubric items provide structured partial credit and localize rubric credit when supporting evidence spans are available. We first obtain an SFT check"},{"source":"arxiv","upvotes":12,"url":"https://arxiv.org/abs/2608.25927","title":"Code World Model: Coding Agent as World Brain","pdf":"https://arxiv.org/pdf/2608.25927.pdf","authors":["Yiwen Chen","Guosheng Lin","Chi Zhang"],"submittedDate":"2026-08-26","tags":["Reasoning","Code Agent","Fine-tuning","World Model"],"arxiv":"https://arxiv.org/abs/2608.25927","date":"2026-08-27","hfUrl":"https://huggingface.co/papers/2608.25927","topics":["Reasoning","Code Agent","Fine-tuning","World Model"],"id":"arxiv:2608.25927","announceDate":"2026-08-27","abstract":"World models aim to simulate how complex environments evolve under actions and events, yet existing video-based world models primarily learn dynamics from visual observations, which reveal outcomes rather than the underlying knowledge, rules, and mechanisms governing world evolution. This makes it difficult to maintain persistent consequences and support coherent, open-ended evolution. We introduce Code World Model, a framework that separates world evolution from visual realization by combining the reasoning and coding capabilities of language models with the generative priors of video models. A coding agent serves as the world brain, reasoning about events and their consequences and generating executable code to maintain persistent world state and perform rule-consistent evolution. To connect executable state with visual generation, we introduce a proxy representation that encodes frame"},{"source":"arxiv","upvotes":1,"url":"https://arxiv.org/abs/2608.25832","title":"Skill Issue: Are Skills Language-Invariant in LLMs?","pdf":"https://arxiv.org/pdf/2608.25832.pdf","authors":["Bobby Cheng","Adam Gaber","Zhengyuan Liu","Catherine Arnett","Omer Goldman","Cheston Tan","Leshem Choshen"],"submittedDate":"2026-08-26","tags":["Reasoning","Evaluation"],"arxiv":"https://arxiv.org/abs/2608.25832","date":"2026-08-27","hfUrl":"https://huggingface.co/papers/2608.25832","topics":["Reasoning","Evaluation"],"id":"arxiv:2608.25832","announceDate":"2026-08-27","abstract":"Large language models access knowledge inconsistently across languages, but to what extent do they differ in their skill sets when interacting with different languages? This work quantifies cross-lingual skill inconsistency orthogonally from knowledge and general benchmark performance. We do this via multilingual self-play: two instances of the same model compete in a text-based game, each interacting through a different language interface. Since the model, opponent, rules, state space, and available actions remain fixed, this setting isolates the effect of language on the model's realized behavior. We build a multilingual extension to TextArena and evaluate three open-weight models across eight languages and six games covering spatial reasoning, imperfect information, resource allocation, and repeated interaction. We find that the same model can exhibit markedly different playing streng"},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.25935","title":"TAU-Agent: An Agentic Retrieval-Augmented Framework for Traffic Anomaly Understanding","pdf":"https://arxiv.org/pdf/2608.25935.pdf","authors":["Yuqiang Lin","Yan Shi","Sam Lockyer","Harish Tayyar Madabushi","Adrian Evans","Wenbin Li","Yinhai Wang","Nic Zhang"],"submittedDate":"2026-08-26","tags":["Agentic RAG","Agentic Search","LLM Training","VLM Training","Reasoning"],"arxiv":"https://arxiv.org/abs/2608.25935","date":"2026-08-27","topics":["Agentic RAG","Agentic Search","LLM Training","VLM Training","Reasoning","Evaluation","Fine-tuning"],"id":"arxiv:2608.25935","announceDate":"2026-08-27","abstract":"Traffic Anomaly Understanding (TAU) requires models and systems to detect, reason about, and explain anomalous events in transportation videos. To address this challenge, we propose TAU-Agent, an agentic retrieval-augmented framework for traffic anomaly understanding. Given a task query, a central retrieval agent orchestrates two visual perception tools, namely a Video Captioning Tool and an Open-Vocabulary Tracking Tool, to retrieve and select query-relevant evidence, including captions, temporal intervals, and object trajectories. The selected evidence, together with sampled video frames and the input query, is provided to a supervised fine-tuned vision-language model for final reasoning and answer generation. We evaluate TAU-Agent on both the in-domain and the out-of-domain benchmarks from the AI City Challenge 2026. TAU-Agent achieves scores of 0.6779 on Track 3, 0.3998 on Track 7, a"},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.25559","title":"AdaVDR: Adaptive Tool Use and Reflection for Video Deep Research","pdf":"https://arxiv.org/pdf/2608.25559.pdf","authors":["Xintong Zhang","Xiaomeng Fan","Shilin Yan","Ekko He","Zicheng Liu","Zijian Zou","Guannan Zhang","Yuwei Wu","Zhi Gao","Hongwei Xue"],"submittedDate":"2026-08-26","tags":["Agentic Search","LLM Training","Tool Use","Reasoning","Evaluation"],"arxiv":"https://arxiv.org/abs/2608.25559","date":"2026-08-27","topics":["Agentic Search","LLM Training","Tool Use","Reasoning","Evaluation","Fine-tuning","Reflection"],"id":"arxiv:2608.25559","announceDate":"2026-08-27","abstract":"Video deep research answers complex questions by jointly understanding video content and retrieving external knowledge from the open Web. However, diverse questions and videos require different tool-use strategies, and inappropriate tool calls can produce incorrect results. Uncertain grounding and retrieval also make unnecessary interactions costly and error-prone, increasing latency and reasoning errors. To address these challenges, we propose AdaVDR, an adaptive video deep research agent with adaptive tool invocation and reflection. AdaVDR selects tools according to the task and its capabilities, and backtracks only when unreliable intermediate results require correction. To enable these capabilities, we develop a video deep research data construction pipeline. We first discover retrieval-relevant events and entities in diverse videos and acquire detailed information through grounding "},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.25756","title":"TailSFT: Filtered Fine-Tuning Improves Post-Training Performance","pdf":"https://arxiv.org/pdf/2608.25756.pdf","authors":["Sadhika Malladi","Samy Jelassi","Dylan Foster","Jordan T. Ash","Akshay Krishnamurthy"],"submittedDate":"2026-08-26","tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2608.25756","date":"2026-08-27","topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"id":"arxiv:2608.25756","announceDate":"2026-08-27","abstract":"Reinforcement learning post-training drives reasoning and agentic capabilities in modern AI systems, yet a growing body of work shows that it is most effective when used to fine-tune an already capable base model. We question whether existing pipelines yield models that are most suitable for reinforcement learning. Building on prior work highlighting the role of coverage and pass@K as predictors of post-RL performance, we design a simple modification to supervised fine-tuning, TailSFT, which filters out already fit sequences during training, thereby focusing learning on under-modeled regions, or the tail, of the data distribution. We justify and validate the design choices in TailSFT, particularly the specific filtering criteria, through a combination of controlled experiments and theoretical analysis. On OLMo-3 7B, TailSFT often improves pass@16 performance on math and coding evaluation"},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.25618","title":"AWM: Answerable Working Memory for Long-Document VQA Agents","pdf":"https://arxiv.org/pdf/2608.25618.pdf","authors":["Dongzhuoran Zhou","Yuqicheng Zhu","Yule Liu","Zhen Yang","Rui Lu","Yuxiao Dong","Jie Tang","Evgeny Kharlamov"],"submittedDate":"2026-08-26","tags":["Agentic RAG","Agentic Search","Post-Training","VLM Training","Memory"],"arxiv":"https://arxiv.org/abs/2608.25618","date":"2026-08-27","topics":["Agentic RAG","Agentic Search","Post-Training","VLM Training","Memory","Evaluation"],"id":"arxiv:2608.25618","announceDate":"2026-08-27","abstract":"Long-document visual question answering increasingly relies on VLM agents that retrieve candidate pages, inspect page images, write findings to working memory, and synthesize answers. Working memory should carry answer-supporting evidence across page inspections for later grounded answering, yet existing evaluation mainly checks final-answer correctness and evidence-page access. This creates a memory-quality blind spot: an agent may reach the right page and answer correctly while leaving behind memory too generic or incomplete to support answering once page context is removed. We introduce \\emph{memory-only answerability}, a diagnostic that asks whether a reader can answer from the question and terminal working memory alone. Building on this diagnostic, \\emph{Answerable Working Memory} (AWM) treats terminal working memory as an answerable evidence artifact, and AWM-GRPO incorporates this"},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.25243","title":"From Memorization to Absorption: Mixed-Policy RL for Continual Knowledge Injection","pdf":"https://arxiv.org/pdf/2608.25243.pdf","authors":["Zhibo Hou","Fan Zhao","Zhiyu An","Wan Du"],"submittedDate":"2026-08-26","tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2608.25243","date":"2026-08-27","topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"id":"arxiv:2608.25243","announceDate":"2026-08-27","abstract":"Continual knowledge injection is essential for keeping large language models up-to-date in a fast-evolving world. Existing methods rely on supervised fine-tuning (SFT), which memorizes injected facts in their training format but fails to generalize across paraphrasing, document combinations, and reasoning. To address this, we propose Golden-GRPO Injection (GRIN), a three-stage self-learning framework for continual knowledge injection. Golden-GRPO is a mixed-policy reinforcement learning algorithm designed specifically for knowledge injection, which injects a golden answer to provide learning signal even when on-policy rollouts fail on novel facts. We further introduce Blank and Counter, two document-level benchmarks targeting novel acquisition and counterfactual overwrite respectively, each evaluating single-fact recall, multi-source retrieval, and inferential reasoning. Our experiments "},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.25777","title":"LocalLSTC: A Long Short-Term Control Architecture for Locally Deployed GUI Agents","pdf":"https://arxiv.org/pdf/2608.25777.pdf","authors":["Weiming Li","Helen Paik","Yulei Sui"],"submittedDate":"2026-08-26","tags":["Reasoning","Planning","Computer Use","Evaluation","Agent Framework"],"arxiv":"https://arxiv.org/abs/2608.25777","date":"2026-08-27","topics":["Reasoning","Planning","Computer Use","Evaluation","Agent Framework"],"id":"arxiv:2608.25777","announceDate":"2026-08-27","abstract":"Modern GUI-agent frameworks achieve strong desktop task performance with frontier API models, yet persistent control information often remains implicit in growing interaction trajectories. At each step, the planner reconstructs the active task stage, accumulated evidence, and runtime feedback before deciding the next action. This dependence becomes more pronounced under weaker local reasoning backbones. Across four representative state-of-the-art frameworks, replacing GPT-5 with Qwen3.5-9B reduces average OSWorld SR-100 from 60.9\\% to 37.7\\%. Trajectory annotation further identifies at least one control failure in 91.6\\% of failed trajectories. To address this problem, we introduce LocalLSTC, a training-free architecture that organizes control by temporal scope, maintaining persistent cross-step state to guide short-term execution commitments. Long-Term Control maintains the active subgo"},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.25518","title":"Agentic Game Development as a Verifiable Trajectory Data Engine for Scaling World Models","pdf":"https://arxiv.org/pdf/2608.25518.pdf","authors":["Pengfei Zhou","Hexin Wang","Zhengfeiyang Zhang","Yixing Ma","Zhenglin Wan","Kaipeng Zhang","Wangbo Zhao","Yang You"],"submittedDate":"2026-08-26","tags":["Post-Training","Code Agent","RL for LLM","Data Engine","World Model"],"arxiv":"https://arxiv.org/abs/2608.25518","date":"2026-08-27","topics":["Post-Training","Code Agent","RL for LLM","Data Engine","World Model"],"id":"arxiv:2608.25518","announceDate":"2026-08-27","abstract":"A common strategy for scaling world models is to train on more crawled video with more compute. We argue that this strategy is inefficient: scaling world models also requires a recursive data engine that offers grounded reward signals. The success of code agents illustrates why this matters. As code is executable, compilers and runtimes can provide high-quality rewards for Reinforcement Learning (RL) post-training of LLMs. By contrast, spatial generation still relies largely on fuzzy proxies such as CLIP scores. These signals are fuzzy and biased, making them hard to support RL post-training. Compared with these, game development provides a missing reward environment for spatial world models. A scene encoded by a game engine is an executable world specification: the engine can efficiently check collision, physics, navigability and bounded playability, while the developer provides the glo"},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.25457","title":"MACGen: Toward Functionally Correct and Secure Code Generation via Multi-Agent Collaboration","pdf":"https://arxiv.org/pdf/2608.25457.pdf","authors":["Miseon Yu","Jaehoon Choi","Younghan Lee","Yunheung Paek"],"submittedDate":"2026-08-26","tags":["Multi-Agent","Planning","Code Agent","Reflection","Agent Framework"],"arxiv":"https://arxiv.org/abs/2608.25457","date":"2026-08-27","topics":["Multi-Agent","Planning","Code Agent","Reflection","Agent Framework"],"id":"arxiv:2608.25457","announceDate":"2026-08-27","abstract":"Despite their strong ability to generate code, large language models often fail to produce secure code, as their outputs frequently contain security vulnerabilities. Secure code generation is inherently challenging because it requires solving a multi-objective problem: functional correctness and security. Existing approaches address this challenge by injecting external security knowledge or by using agentic feedback and iterative refinement. However, guideline retrieval often leaves the generator to translate generic advice into task-specific secure implementations, while shared-dialogue multi-agent feedback can blur role boundaries and suffer from context bloat. We present MACGen, a multi-agent framework that integrates planning, security analysis, code synthesis and refinement to jointly optimize security and functionality. A planner constructs a step-by-step plan to satisfy functional"},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.25452","title":"VGA-BenchV2: An Expanded Unified Benchmark and Multi-Model Framework for Evaluating Video Aesthetics and Generation Quality","pdf":"https://arxiv.org/pdf/2608.25452.pdf","authors":["Longteng Jiang","DanDan Zheng","Qianqian Qiao","Heng Huang","Huaye Wang","Yihang Bo","Bao Peng","Jingdong Chen","Jun Zhou","Xin Jin"],"submittedDate":"2026-08-26","tags":["Post-Training","VLM Training","Evaluation","Alignment","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2608.25452","date":"2026-08-27","topics":["Post-Training","VLM Training","Evaluation","Alignment","Fine-tuning"],"id":"arxiv:2608.25452","announceDate":"2026-08-27","abstract":"We introduce VGA-BenchV2, an extended human-aligned benchmark and optimization framework for jointly evaluating and improving video generation quality and aesthetic value. Built upon VGA-Bench, VGA-BenchV2 preserves the original fine-grained taxonomy with two primary dimensions-Aesthetic and Generation-and 52 sub-dimensions. Guided by this taxonomy, we curate 1,016 diverse prompts and collect over 60,000 videos generated by 12 mainstream video generation models. More importantly, VGA-BenchV2 substantially expands human-labeled supervision by adding 36,000 task-level annotations, including 16,200 for aesthetic quality, 13,200 for aesthetic tagging, and 6,600 for generation quality, corresponding to 13.46x, 11.15x, and 1.55x scale-ups over VGA-Bench, respectively. Leveraging this enlarged annotation corpus, we develop a hybrid evaluator architecture consisting of VAQA-Net for continuous ae"},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.26053","title":"$R^3$: Training Robots to Reason in Natural Language via Reinforcement Learning","pdf":"https://arxiv.org/pdf/2608.26053.pdf","authors":["Lehong Wu","Yuxiao Qu","Zheyuan Hu","Ivan Zhang","Limin Wei","Zackory Erickson","Aviral Kumar"],"submittedDate":"2026-08-26","tags":["Post-Training","VLM Training","Reasoning","Evaluation","RL for LLM"],"arxiv":"https://arxiv.org/abs/2608.26053","date":"2026-08-27","topics":["Post-Training","VLM Training","Reasoning","Evaluation","RL for LLM"],"id":"arxiv:2608.26053","announceDate":"2026-08-27","abstract":"Reasoning in language allows foundation models to spend more test-time compute on hard problems, such as those requiring decomposition, constraint tracking, and prediction of future consequences. Whether this mechanism can improve robotic manipulation remains unclear, where long-horizon tasks require tracking partial progress, reasoning about object relations, recovering from mistakes, and steering noisy low-level policies. In this paper, we study whether VLMs can be trained to reason directly in natural language to guide low-level manipulation policies. We introduce $R^3$, a simple post-training recipe that turns off-the-shelf VLMs into robotic reasoners: it first mid-trains a VLM on expert-generated reasoning traces to initialize the desired reasoning style, then improves the reasoner with single-step rubric-based RL from offline action data. Unlike prior robotic reasoning methods that"},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.24888","title":"SIMGUIDE: Procedurally Grounded Multi-Context Representations for Personalized Agent Planning","pdf":"https://arxiv.org/pdf/2608.24888.pdf","authors":["Chirag Shah"],"submittedDate":"2026-05-14","tags":["Agentic RAG","Agentic Search","Planning","Evaluation","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2608.24888","date":"2026-08-27","topics":["Agentic RAG","Agentic Search","Planning","Evaluation","Fine-tuning"],"id":"arxiv:2608.24888","announceDate":"2026-08-27","abstract":"Personalized AI agents overwhelmingly treat users as single entities: a flat profile concatenated into a prompt. This fails when the same person holds different priorities across life contexts -- and fails catastrophically when those priorities conflict. The core problem is not that agents lack information about users; it is that the format of user representations determines whether an agent can act on that information at all. We introduce SIMGUIDE, a method that structures user context into typed, domain-specific blocks called Sims and grounds each constraint with procedural examples drawn from past decisions. To evaluate this, we construct SIMBENCH, a diagnostic suite of 47 preference-conditioned planning tasks where the correct plan depends on which user context is active -- a property no existing benchmark tests. Declarative Sim constraints alone do not outperform retrieval-based per"},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.25937","title":"Candidate supply and answer selection shape the value of LLM judging in multi-agent systems","pdf":"https://arxiv.org/pdf/2608.25937.pdf","authors":["Jia-Hao Ji","Sijie Li","Jiabei Cheng","Zixi She","Jin-Tai Yu","Zhiyuan Yuan"],"submittedDate":"2026-08-26","tags":["Multi-Agent","Reasoning","Evaluation","Agent Framework"],"arxiv":"https://arxiv.org/abs/2608.25937","date":"2026-08-27","topics":["Multi-Agent","Reasoning","Evaluation","Agent Framework"],"id":"arxiv:2608.25937","announceDate":"2026-08-27","abstract":"Multi-agent systems (MAS) sometimes already have the potential to answer correctly, but still report a wrong answer. Explaining this outcome is difficult because generation, communication and final answer-selection rules usually change simultaneously. We conceptualize multi-agent reasoning as an evolutionary pipeline of candidate generation, peer communication and terminal selection, wherein consensus without quality control can exhibit patterns of memetic drift. We study two questions: (1) when an LLM judge provides effective selection pressure by supplying a signal of answer correctness for candidates generated in a multi-agent system, and (2) when using that signal improves the reported answer. To map judge reliability, we analysed 15,336 questions from MMLU-Pro, GPQA, MedXpertQA and MuSR, with Humanity's Last Exam analysed separately. To test these rules, we replayed 81,390 fixed can"},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.25417","title":"Paint What You See: Benchmarking Dexterous Visual Tool Use in Multimodal Agents","pdf":"https://arxiv.org/pdf/2608.25417.pdf","authors":["Shudong Liu","Dongyang Chen","Enci Zhang","Jinwei Liang","Zheng Ma","Lewei Lu"],"submittedDate":"2026-08-26","tags":["Tool Use","Planning","Evaluation","Multimodal Agent"],"arxiv":"https://arxiv.org/abs/2608.25417","date":"2026-08-27","topics":["Tool Use","Planning","Evaluation","Multimodal Agent"],"id":"arxiv:2608.25417","announceDate":"2026-08-27","abstract":"Evaluation is shifting from static QA toward agentic settings where models act through external tools. We identify a critical yet underexplored capability within this space - dexterous visual tool use: fine-grained, closed-loop parameterized visual action in which models infer tool parameters from visual evidence, and those parameters directly govern the final result. Existing benchmarks cover web navigation, GUI operation, and software engineering, but rarely target this coupling between visual evidence and execution precision. We propose EASEL, a benchmark evaluating a controlled instance of dexterous visual tool use that adopts reference-guided visual reconstruction as its primary proxy task: the agent incrementally paints a canvas to match a reference image. EASEL additionally includes semantic tasks spanning region annotation, handwriting, and path planning. We further provide EASEL"},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.25039","title":"LifePlanner: Evaluating LLM Agents for Geo-spatial Planning with Social Media Data","pdf":"https://arxiv.org/pdf/2608.25039.pdf","authors":["Zhen Dong","Yuning Peng","Yutao Shi","Lei Zhong","Yongsen Mao","Yuan Liu","Haiping Wang"],"submittedDate":"2026-08-25","tags":["Tool Use","Reasoning","Planning","Evaluation"],"arxiv":"https://arxiv.org/abs/2608.25039","date":"2026-08-27","topics":["Tool Use","Reasoning","Planning","Evaluation"],"id":"arxiv:2608.25039","announceDate":"2026-08-27","abstract":"Geo-spatial planning, like trip design, is a realistic testbed for LLM agents because it requires grounded tool use, noisy evidence retrieval, and multi-constraint reasoning. Most benchmarks, however, only provide clean geospatial data and tools, missing the open-ended social signals that people use in daily planning. We introduce LifePlanner, a benchmark that enriches map data with large-scale local social media posts and provides access through an MCP toolset. LifePlanner provides an evaluation suite spanning four task categories and three difficulty levels. Experiments show frontier LLMs perform well on simple retrieval but degrade sharply on complex planning, with the Pass Rate dropping to 40.2%. Results show that failures mainly stem from incomplete evidence acquisition from such a large multimodal database, imprecise tool use, and weak constraint integration rather than model size "},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.25487","title":"ReliableRAG: Combating Misinformation in Retrieval-Augmented Generation via Reliability-Guided Reasoning Chains","pdf":"https://arxiv.org/pdf/2608.25487.pdf","authors":["Jinpu Jiang","Xuan Wu","Wenhao Song","Bo Yang","You Zhou","Hongwei Ge","Heow Pueh Lee","Yanchun Liang","Chunguo Wu"],"submittedDate":"2026-08-26","tags":["Agentic RAG","Agentic Search","Reasoning","Alignment"],"arxiv":"https://arxiv.org/abs/2608.25487","date":"2026-08-27","topics":["Agentic RAG","Agentic Search","Reasoning","Alignment"],"id":"arxiv:2608.25487","announceDate":"2026-08-27","abstract":"Retrieval-Augmented Generation (RAG) has emerged as a powerful architecture for Question Answering (QA) by integrating external information into Large Language Models (LLMs). However, false, inaccurate, and misleading information in news and social media poses a serious challenge to real-world RAG systems, especially in multi-hop QA, where complex multi-step reasoning can be misled by even a single deceptive misinformation segment in the retrieved documents. Existing approaches mainly rely on implicit alignment or explicit regulation, but their limited ability to assess fine-grained information reliability makes them vulnerable to deceptive misinformation that is semantically relevant to the question yet factually incorrect, leading to erroneous answers. To address this limitation, we propose ReliableRAG, which, to the best of our knowledge, is the first reliability-driven framework that"},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.25486","title":"PonsRAG: A Pons-Inspired RAG Bridging Cognitive Islands for Coordinated Long Narrative Reasoning","pdf":"https://arxiv.org/pdf/2608.25486.pdf","authors":["Rongchen Zhao","Yu Chen","Juyuan Wang","Zhouting Mo","Jianxing Yu","Wenqing Chen","Jingping Liu"],"submittedDate":"2026-08-26","tags":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"arxiv":"https://arxiv.org/abs/2608.25486","date":"2026-08-27","topics":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"id":"arxiv:2608.25486","announceDate":"2026-08-27","abstract":"Long Narrative Reasoning is an essential capability for processing and reasoning over complex narratives. While retrieval-augmented generation provides a promising framework, existing methods still face two critical challenges: cognitive islanding and cross-layer evidence disconnection. To address these issues, we propose PonsRAG, a coordinated RAG framework inspired by the biological pons. PonsRAG consists of two key components: Triple-Layer Indexing, which organizes documents into a connected knowledge structure to bridge cognitive islands, and Coordinated Reasoning, which retrieves evidence across distinct layers and integrates cross-layer information into a unified context. We evaluate PonsRAG on four long-context narrative benchmarks, and experimental results show that it outperforms the strongest baseline, achieving a 11.56% relative improvement in average accuracy on multi-choice "},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.25123","title":"SelfGraphRAG: Bridging the Supervision Gap in Graph-Based RAG with Synthetic QA Generation","pdf":"https://arxiv.org/pdf/2608.25123.pdf","authors":["Ben Lagnese","Manas Gaur"],"submittedDate":"2026-08-25","tags":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"arxiv":"https://arxiv.org/abs/2608.25123","date":"2026-08-27","topics":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"id":"arxiv:2608.25123","announceDate":"2026-08-27","abstract":"Retrieval-augmented generation (RAG) improves large language models by incorporating external knowledge without retraining, but existing methods often underuse the relational structure encoded in knowledge graphs. Graph-based RAG can capture entity relationships, yet supervised graph retrieval typically requires labeled question-answer data that may not be available for newly constructed graphs. We address this limitation with SelfGraphRAG, a framework that generates question-answer pairs directly from knowledge graph structure and uses them to train a query-conditioned graph retriever. The generated questions capture multi-hop paths and local neighborhoods, providing relational supervision without manual annotation. Experiments on multi-hop question answering and classification benchmarks show that SelfGraphRAG improves retrieval precision and downstream reasoning performance over embed"},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.24977","title":"Retrieved But Not Reliable: A Survey on Attacks, and Defenses in Retrieval-Augmented Generation","pdf":"https://arxiv.org/pdf/2608.24977.pdf","authors":["Minh Tran","Cuong Dang","Tuc Nguyen","Khanh-Tung Tran","Minh Huynh Nguyen","Trinh Chau","Kien Le","Do Xuan Long","Jiahao Zhang","Hoang D. Nguyen","Thanh Le","Suhang Wang"],"submittedDate":"2026-08-25","tags":["Agentic RAG","Agentic Search","Hallucination","Evaluation"],"arxiv":"https://arxiv.org/abs/2608.24977","date":"2026-08-27","topics":["Agentic RAG","Agentic Search","Hallucination","Evaluation"],"id":"arxiv:2608.24977","announceDate":"2026-08-27","abstract":"Retrieval-Augmented Generation (RAG) enhances large language models by grounding outputs in external knowledge, improving factuality and reducing hallucinations. At the same time, the retrieval-augmented pipeline introduces new robustness and security risks, including corpus poisoning, backdoor attacks, privacy leakage, and fairness violations. Despite rapid progress in this area, existing surveys remain limited in their treatment of attacker objectives, threat models, and stage-specific defenses across the full RAG pipeline. This survey presents a unified and pipeline-aware overview of RAG robustness. We formalize threat models over the corpus, retriever, and generator, and organize attacks into three main objectives: accuracy, privacy, and fairness. We further review defenses from a pipeline-aware perspective, covering the retrieval, rerank, generation, and traceback stages. In additio"},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.24949","title":"Demystifying Reinforcement Learning Post-Training of Language Models","pdf":"https://arxiv.org/pdf/2608.24949.pdf","authors":["Donovan Clay","Saket Gollapudi","Sankar Harilal","Min Jang","Jacob Morrison","Sewoong Oh","Natasha Jaques"],"submittedDate":"2026-08-24","tags":["Post-Training","LLM Training","Reasoning","RL for LLM"],"arxiv":"https://arxiv.org/abs/2608.24949","date":"2026-08-27","topics":["Post-Training","LLM Training","Reasoning","RL for LLM"],"id":"arxiv:2608.24949","announceDate":"2026-08-27","abstract":"Reinforcement learning (RL) post-training has emerged as a powerful framework for enhancing the capabilities of large language models (LLMs), enabling impressive reasoning, math, and coding capabilities. Yet for many researchers and practitioners, the principles behind classical RL remain a \"black box\". In this work, we deconstruct the RL post-training algorithm, investigating each step to clarify what is actually happening beneath the surface. By isolating the mechanics of RL with Verifiable Rewards in a controlled and simplified environment, we examine how RL outcomes are shaped by the base model's prior distribution, the granularity of the reward signal, the diversity of the prompt distribution, and model scale. We use the entropy of the policy's output distribution as a lens to compare the distributions learned through pretraining, SFT, and RL post-training, revealing how each stage "},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.24988","title":"Does Fine-Tuning Undo Activation Steering? Behavioural Recovery Without Weight-Edit Reversal","pdf":"https://arxiv.org/pdf/2608.24988.pdf","authors":["Philipp E. Glass","Allan Tucker","Yongmin Li","Alina Miron"],"submittedDate":"2026-08-25","tags":["Post-Training","LLM Training","Alignment","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2608.24988","date":"2026-08-27","topics":["Post-Training","LLM Training","Alignment","Fine-tuning"],"id":"arxiv:2608.24988","announceDate":"2026-08-27","abstract":"Activation steering can be embedded directly into a language model's weights, shaping behaviour without inference-time intervention and offering a way to encode alignment prior to release. However, models are routinely fine-tuned after deployment, and it is unknown whether embedded interventions survive this. We study the stability of embedded steering for refusal suppression and brevity induction across five instruction-tuned models (3B-14B) under non-adversarial SFT and RLHF. Behaviourally, preservation tracks the training data: steering degrades when optimisation pressure contradicts the targeted behaviour and persists otherwise, with refusal ablation losing 64% of its effect on average under SFT. Mechanistically, however, the weight edit survives almost untouched even where behaviour reverts: mean vector recovery is $ρ= 0.004$, and the fine-tuning update along the steering direction "},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.25826","title":"Unfolding Scientific Papers into Multi-Turn Generation Trajectories for Continued Pre-Training","pdf":"https://arxiv.org/pdf/2608.25826.pdf","authors":["Qiankai Xu","Qiguang Chen","Zixin Su","Wenhao Huang","Yue Gao","Jiaheng Liu","Ge Zhang"],"submittedDate":"2026-08-26","tags":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2608.25826","date":"2026-08-27","topics":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"id":"arxiv:2608.25826","announceDate":"2026-08-27","abstract":"A recent line of synthetic-data work reconstructs the thinking behind existing text rather than rewriting the text itself, but it operates on short web passages, recovers only local thoughts, and leaves the structure of whole documents untouched. Scientific papers are written to a clear and largely uniform structure and make a natural substrate for lifting this paradigm to the document level. We present a pipeline that unfolds each paper into a multi-turn generation trajectory in which a teacher model reconstructs the writing process of the whole paper: a writing request, a global plan, and pre-writing deliberation for each section. All section texts and the abstract are kept verbatim from the source paper. We apply the pipeline to quality-filtered arXiv papers and obtain a corpus for continued pre-training (CPT) that is roughly twice the size of the source text. The same reverse constru"},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.25428","title":"DCGC: Draft-Conditioned Global Correction for Complex Reasoning with Masked Diffusion Models","pdf":"https://arxiv.org/pdf/2608.25428.pdf","authors":["Minhae Oh","Nakyung Lee","Jungwoo Lee"],"submittedDate":"2026-08-26","tags":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2608.25428","date":"2026-08-27","topics":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"id":"arxiv:2608.25428","announceDate":"2026-08-27","abstract":"Correcting flawed reasoning traces remains a significant challenge for Large Language Models (LLMs), whose autoregressive generation can propagate early mistakes into subsequent reasoning. We introduce DCGC, a Masked Diffusion Model (MDM) framework for global correction that uses an imperfect solution draft from an upstream solver as auxiliary context. DCGC combines task-specific Supervised Fine-Tuning (SFT) with a novel inference-time mechanism called Dynamic Dual-CFG. This mechanism separates problem-only and joint problem-draft branches and scales the draft-conditioned residual using a relative confidence gap. Across math, code, and knowledge reasoning benchmarks, DCGC outperforms standard sampling and simpler CFG variants, with additional results suggesting transfer to different diffusion backbones. In test-time setting where ground-truth failure labels are unavailable, DCGC improves"},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.24966","title":"Targeting the Attention Heads Behind Object Hallucination in LLaVA","pdf":"https://arxiv.org/pdf/2608.24966.pdf","authors":["Armaan Sandhu","Abhilasha Senapati","Hima Kammachi"],"submittedDate":"2026-08-25","tags":["VLM Training","Hallucination","Interpretability","Fine-tuning"],"arxiv":"https://arxiv.org/abs/2608.24966","date":"2026-08-27","topics":["VLM Training","Hallucination","Interpretability","Fine-tuning"],"id":"arxiv:2608.24966","announceDate":"2026-08-27","abstract":"Vision-language models such as LLaVA-1.5-7B often hallucinate objects absent from the image when generating captions. We ask whether an interpretability diagnosis of this failure can guide a targeted fix, and we measure what that fix actually changes. We rank attention heads by how much their image attention drops around hallucinated object words, then screen the shortlist by ablating candidate heads and measuring the change in hallucination-token log probability, yielding a 32-head set. We restrict two interventions to these heads: a head-sliced LoRA adapter and an inference-time grounding controller. On 400 held-out COCO images, the combined method lowers CHAIRs (the fraction of captions with a hallucinated object) from 0.370 to 0.230 and CHAIRi (the fraction of hallucinated object mentions) from 0.156 to 0.096 (p < 0.001, paired sign-flip tests). Two controls sharpen attribution. A ra"},{"source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2608.25960","title":"LivingRAG: Augmenting Graph RAG with Experience","pdf":"https://arxiv.org/pdf/2608.25960.pdf","authors":["Yuzhuo Cui","Zongye Zhang","Qingjie Liu"],"submittedDate":"2026-08-26","tags":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"arxiv":"https://arxiv.org/abs/2608.25960","date":"2026-08-27","topics":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"id":"arxiv:2608.25960","announceDate":"2026-08-27","abstract":"Graph-based RAG improves multi-hop question answering by organizing evidence as a knowledge graph. However, most existing RAG systems process each query in isolation and discard useful reasoning from the LLM's response after inference. As a result, later related queries need to retrieve evidence and reason from scratch. We propose LivingRAG, a Graph RAG framework with writable and reusable reasoning experience. LivingRAG adds a writable experience store to a graph-based retrieval backbone, enabling verified experiences to be reused during inference in two ways. Stored graph signals help retrieval find entities and passages that were useful in earlier related queries. Stored summaries provide a reference reasoning pattern for answer generation. We analyze online QA streams and find reusable signals from shared entities, graph neighborhoods, and question templates. Experiments on multi-hop"}],"archive":[],"latestPath":"data/latest.json"};
